            .compute_root()
            .split(j, jo, ji, 16)
            .parallel(jo)
            .vectorize(i, vec_width);

        // Reduction update schedule
        cov_sum
            .update()
            .split(j, jo, ji, 16)
            .parallel(jo)
            .vectorize(i, vec_width);
